//! Two small JPEG files (16 x 16, gray, baseline), made once with libjpeg from a pattern of 4 x 4
//! squares: `SECRET` has the pattern everywhere, `BLANK_TOP` has it only in the lower 8 rows and is
//! white above. They are kept as hex so that the tests need no encoder.

/// The bytes of a hex string.
pub fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

pub const SECRET_HEX: &str = "";

pub const BLANK_TOP_HEX: &str = "";
